CREATE TABLE ezcontentclass_attribute (id SERIAL NOT NULL, version INT DEFAULT 0 NOT NULL, can_translate INT DEFAULT 1, category VARCHAR(25) DEFAULT '' NOT NULL, contentclass_id INT DEFAULT 0 NOT NULL, data_float1 DOUBLE PRECISION DEFAULT NULL, data_float2 DOUBLE PRECISION DEFAULT NULL, data_float3 DOUBLE PRECISION DEFAULT NULL, data_float4 DOUBLE PRECISION DEFAULT NULL, data_int1 INT DEFAULT NULL, data_int2 INT DEFAULT NULL, data_int3 INT DEFAULT NULL, data_int4 INT DEFAULT NULL, data_text1 VARCHAR(255) DEFAULT NULL, data_text2 VARCHAR(50) DEFAULT NULL, data_text3 VARCHAR(50) DEFAULT NULL, data_text4 VARCHAR(255) DEFAULT NULL, data_text5 TEXT DEFAULT NULL, data_type_string VARCHAR(50) DEFAULT '' NOT NULL, identifier VARCHAR(50) DEFAULT '' NOT NULL, is_information_collector INT DEFAULT 0 NOT NULL, is_required INT DEFAULT 0 NOT NULL, is_searchable INT DEFAULT 0 NOT NULL, is_thumbnail BOOLEAN DEFAULT 'false' NOT NULL, placement INT DEFAULT 0 NOT NULL, serialized_data_text TEXT DEFAULT NULL, serialized_description_list TEXT DEFAULT NULL, serialized_name_list TEXT NOT NULL, PRIMARY KEY(id, version));
